function f = HS55_f(x)
f = x(1) + 2*x(2) + 4*x(5) + exp(x(1).*x(4));
end

function g = HS55_g(x)
g = zeros(6, 1);
g(1) = x(4).*exp(x(1).*x(4)) + 1;
g(2) = 2;
g(4) = x(1).*exp(x(1).*x(4));
g(5) = 4;
end

function c = HS55_c(x)
c = zeros(6, 1);
c(1) = x(1) + 2*x(2) + 5*x(5) - 6;
c(2) = x(1) + x(2) + x(3) - 3;
c(3) = x(4) + x(5) + x(6) - 2;
c(4) = x(1) + x(4) - 1;
c(5) = x(2) + x(5) - 2;
c(6) = x(3) + x(6) - 2;
end

